 def frullani(m):
  A=s.log(m)
  return p(r'\int_0^\infty\frac{e^{-x}-e^{-'+L(m)+r'x}}x\,dx',A,[(s.log(m)/m,'retain an extra scale Jacobian'),(s.log(m-1),'subtract parameters inside a logarithm'),(s.log(m+1),'add rather than compare decay parameters')],['Write (e^-x-e^-mx)/x=integral_1^m e^-tx dt. Tonelli applies to the nonnegative integrand.','Integrating first in x gives integral_1^m dt/t=log m. The combined integrand has a finite limit at zero and exponential decay at infinity.'],[E(s.integrate(s.exp(-t*x),(t,1,m)),(s.exp(-x)-s.exp(-m*x))/x),E(s.integrate(1/t,(t,1,m)),A),E(s.limit((s.exp(-x)-s.exp(-m*x))/x,x,0),m-1)],'Frullani-positive-parameter-rectangle',['m>=4, so the auxiliary parameter rectangle is positively oriented.'],'Tonelli-and-positive-exponential-parameter-integral')
 def doublelog(m):
  A=s.harmonic(m+1)/(m+1)**2-(s.pi**2/6-s.harmonic(m+1,2))/(m+1)
