 def inversecurvature(m):
  # f+m log f=x, so derivative flow wrt y=f is d/dx=y/(y+m) d/dy.
  fp=x/(x+m);fpp=s.diff(fp,x)*fp;D=s.factor(s.diff(fpp,x));A=4/(27*m)
