 def cube_cap(m):
  n=int(m);cut=m/3;A=sum((-1)**j*s.binomial(m,j)*(cut-j)**m for j in range(int(s.floor(cut))+1))/s.factorial(m)
  # Independent finite exact integration of convolution pieces; no inclusion-exclusion formula used here.
  pieces=[x] # CDF for one coordinate, on [0,1].
  for dim in range(2,n+1):
   old=pieces; cumulative=[s.Integer(0)];ant=[]
   for j,F in enumerate(old):
    primitive=s.integrate(F,x);G=cumulative[-1]+primitive-primitive.subs(x,j);ant.append(G)
    cumulative.append(s.simplify(G.subs(x,j+1)))
   def integ_piece(index,shift):
    if index<0:return s.Integer(0)
    if index>=len(old):return cumulative[-1]+x-shift-len(old)
    return ant[index].subs(x,x-shift)
   pieces=[s.expand(integ_piece(j,0)-integ_piece(j-1,1)) for j in range(dim)]
  actual=pieces[min(n-1,int(s.floor(cut)))].subs(x,cut)
  return p(T('Find the volume in ')+r'\mathbb R^{'+L(m)+r'}'+T(' of ')+r'\{0\le x_j\le1:\ \sum_{j=1}^{'+L(m)+r'}x_j\le '+L(cut)+r'\}.',A,[(cut**m/s.factorial(m),'ignore caps beyond coordinate upper bounds'),(sum((-1)**j*s.binomial(m,j)*(cut-j)**(m+1) for j in range(int(s.floor(cut))+1))/s.factorial(m+1),'integrate an extra height factor instead of volume'),(1-A,'take the complementary cap')],['Without coordinate upper bounds the positive simplex has volume t^m/m!. For each subset of j coordinates exceeding one, translate those coordinates down by one.','Inclusion-exclusion gives (1/m!) sum_(j<=floor t)(-1)^j binomial(m,j)(t-j)^m, with t=m/3. Terms at t-j=0 have zero volume.','An independent piecewise-polynomial convolution of m unit-interval indicators verifies the displayed rational volume exactly.'],[E(actual,A)],'high-dimensional-cube-simplex-cap',['Boundary hyperplanes have zero volume.','Each translated cap is a positive simplex; exactly binomial(m,j) subsets have size j.'],'geometric-inclusion-exclusion-versus-independent-convolution')
 def winding(m):
  Rr=1+1/m;zz=s.symbols('z');Q=sum((m-1-j)*zz**j for j in range(int(m)-1));poly=zz**m-m*zz+m-1
